// Synthetic FAQ - replace with your own approved content or a RAG tool (Lab 04).
const faq = [
  { id: 'FAQ-01', keywords: ['password', 'reset', 'forgot', 'locked'], answer: 'Reset your password at the self-service portal (Start menu > Northwind Self Service > Reset Password). After 5 failed attempts the account locks for 15 minutes.' },
  { id: 'FAQ-02', keywords: ['vpn', 'remote', 'disconnect', 'connect'], answer: 'Use the Northwind VPN client. If it disconnects, check your internet connection, then sign out and back in. VPN sessions time out after 12 hours.' },
  { id: 'FAQ-03', keywords: ['laptop', 'slow', 'hardware', 'replace', 'broken'], answer: 'For slow laptops, restart and install pending updates. Hardware faults or replacements need a ticket; standard replacement time is 3 business days.' },
  { id: 'FAQ-04', keywords: ['email', 'outlook', 'mailbox', 'phishing'], answer: 'Mailbox limit is 50 GB. Report suspicious emails with the Report Phishing button; do not click links or open attachments.' },
  { id: 'FAQ-05', keywords: ['mfa', 'authenticator', 'new phone', 'token'], answer: 'If you changed phones, MFA must be re-registered by the service desk after identity verification. Ask to be escalated.' }
];
const q = String(query || '').toLowerCase();
const scored = faq
  .map(f => ({ ...f, score: f.keywords.filter(k => q.includes(k)).length }))
  .filter(f => f.score > 0)
  .sort((a, b) => b.score - a.score)
  .slice(0, 2);
if (scored.length === 0) return 'NO_MATCH';
return scored.map(f => `[${f.id}] ${f.answer}`).join('\n');

// Simulated escalation. In production, replace with a ticketing integration
// (e.g. Jira, ServiceNow, Zendesk node) using a least-privilege credential.
const id = 'ESC-' + Date.now().toString().slice(-6);
const summary = String(query || '').slice(0, 300);
return `Escalation ${id} created. Summary: ${summary}. A human agent will reply within 4 business hours.`;
